description: Remaining Drive-only data per root
command: SP="C:/Users/User/AppData/Local/Temp/claude/--192-168-100-169-Comun-/aca2a15e-9ccb-4b1b-b3a6-5a5ede318958/scratchpad"; python - "$SP" <<'EOF'
import csv,os,sys,collections,glob
sp=sys.argv[1]
done=set();donef=set()
for fn in glob.glob(os.path.join(sp,'results_[0-9].tsv'))+glob.glob(os.path.join(sp,'results2_*.tsv')):
    for l in open(fn,encoding='utf-8'):
        p=l.rstrip(chr(10)).split(chr(9))
        if p[0] in('OK','ALREADY','ERROR'): done.add(p[3].split(' (')[0])
for fn in glob.glob(os.path.join(sp,'results_files*.tsv')):
    for l in open(fn,encoding='utf-8'):
        p=l.rstrip(chr(10)).split(chr(9))
        if p[0] in('OK','ALREADY'): donef.add(p[1])
done.add('My PC/Comun/Dep. ONLINE/Denisa Radu/New folder (2)')
c=collections.defaultdict(lambda:collections.Counter())
for st,p,mb,lp,i in list(csv.reader(open(os.path.join(sp,'comparatie.csv'),encoding='utf-8-sig'),delimiter=';'))[1:]:
    parts=p.split('/')
    if any('/'.join(parts[:k]) in done for k in range(1,len(parts))) or i in donef: continue
    top='/'.join(parts[:2]) if parts[0]!='Contul meu Drive' else 'Contul meu Drive'
    c[top][st+'_n']+=1; c[top][st+'_gb']+=float(mb)/1000
for t,v in c.items(): print(t, {k:round(x,2) for k,x in v.items()})
EOF
